window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a4e5a10a9ef049c0"]={"versions": [{"id": "FIG-a4e5a10a9ef049c0", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform (Metamodell-Ausschnitt des Manifests, Paket <code>M2::AUTOSARTemplates::AdaptivePlatform::ApplicationDesign::PortInterface::REST</code>). Das Diagramm spezifiziert die Metaklassen zur strukturellen Modellierung von REST-Elementen und deren Eigenschaftsdefinitionen (<code>REST elements</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>RestElementDef</strong> (spezialisiert <code>Identifiable</code>): Repräsentiert die Definition eines REST-Elements.</li>\n<li>Komposition <code>+property</code> [1..*] auf die abstrakte Metaklasse <code>RestAbstractPropertyDef</code>.</li>\n<li><strong>RestAbstractPropertyDef</strong> (spezialisiert <code>AtpStructureElement</code>, abstrakt): Basisklasse für Eigenschaften eines REST-Elements.</li>\n<li>Spezialisierungen: <code>RestPrimitivePropertyDef</code> (abstrakt) und <code>RestArrayPropertyDef</code>.</li>\n<li><strong>RestArrayPropertyDef</strong>: Modelliert Eigenschaften mit Array-Semantik.</li>\n<li>Komposition <code>+element</code> [1] auf <code>RestPrimitivePropertyDef</code>.</li>\n<li><strong>RestPrimitivePropertyDef</strong> (abstrakt): Basisklasse für primitive Eigenschaftsdefinitionen.</li>\n<li>Spezialisierungen: <code>RestStringPropertyDef</code>, <code>RestBooleanPropertyDef</code>, <code>RestAbstractNumericalPropertyDef</code> (abstrakt) sowie <code>RestObjectRef</code>.</li>\n<li><strong>RestStringPropertyDef</strong>:</li>\n<li>Attribut: <code>+ format :String [0..1]</code></li>\n<li>Komposition <code>+enum</code> [1..*] auf <code>RestEnumeratorDef</code>.</li>\n<li><strong>RestEnumeratorDef</strong>:</li>\n<li>Attribut: <code>+ value :String</code></li>\n<li><strong>RestBooleanPropertyDef</strong>: Keine eigenen Attribute modelliert.</li>\n<li><strong>RestAbstractNumericalPropertyDef</strong> (abstrakt):</li>\n<li>Attribute: <code>+ lowerLimit :Limit [0..1]</code>, <code>+ resolution :Float [0..1]</code>, <code>+ unit :String [0..1]</code>, <code>+ upperLimit :Limit [0..1]</code></li>\n<li>Spezialisierungen: <code>RestIntegerPropertyDef</code> und <code>RestNumberPropertyDef</code>.</li>\n<li><strong>RestIntegerPropertyDef</strong> / <strong>RestNumberPropertyDef</strong>: Konkrete Spezialisierungen ohne zusätzliche eigene Attribute im Diagramm.</li>\n<li><strong>RestObjectRef</strong>:</li>\n<li>Attribut: <code>+ role :String</code></li>\n<li>Assoziation / Referenz <code>+object</code> [0..*] zurück auf <code>RestElementDef</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Struktur von REST-Dienstbeschreibungen im AUTOSAR-Manifest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Modellierungswerkzeuge für AUTOSAR Adaptive Manifeste müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>RestElementDef</code> muss mindestens eine Eigenschaft besitzen (<code>+property</code> [1..*]).</li>\n<li>Eigenschaften können primitiv (<code>RestPrimitivePropertyDef</code>) oder als Array (<code>RestArrayPropertyDef</code>) ausgeprägt sein.</li>\n<li>Ein <code>RestArrayPropertyDef</code> referenziert über Komposition genau ein primitives Basiselement (<code>+element</code> [1]).</li>\n<li>Enumerationen werden über <code>RestStringPropertyDef</code> abgebildet, das mindestens einen <code>RestEnumeratorDef</code> über <code>+enum</code> [1..*] aggregieren kann.</li>\n<li>Komplexe Objektstrukturen und Schachtelungen werden über <code>RestObjectRef</code> realisiert, das auf <code>RestElementDef</code> (<code>+object</code> [0..*]) verweist und über das Attribut <code>role</code> semantisch qualifiziert wird.</li>\n<li>Numerische Grenzwerte und Auflösungen (<code>Limit</code>, <code>Float</code>, <code>Unit</code>) sind optional auf Ebene von <code>RestAbstractNumericalPropertyDef</code> definierbar.</li>\n</ul>"}, {"id": "FIG-288472df44790296", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform (Metamodell-Ausschnitt des Manifests, Paket <code>M2::AUTOSARTemplates::AdaptivePlatform::ApplicationDesign::PortInterface::REST</code>). Das Diagramm spezifiziert die Metaklassen zur strukturellen Modellierung von REST-Elementen und deren Eigenschaftsdefinitionen (<code>REST elements</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>RestElementDef</strong> (spezialisiert <code>Identifiable</code>): Repräsentiert die Definition eines REST-Elements.</li>\n<li>Komposition <code>+property</code> [1..*] auf die abstrakte Metaklasse <code>RestAbstractPropertyDef</code>.</li>\n<li><strong>RestAbstractPropertyDef</strong> (spezialisiert <code>AtpStructureElement</code>, abstrakt): Basisklasse für Eigenschaften eines REST-Elements.</li>\n<li>Spezialisierungen: <code>RestPrimitivePropertyDef</code> (abstrakt) und <code>RestArrayPropertyDef</code>.</li>\n<li><strong>RestArrayPropertyDef</strong>: Modelliert Eigenschaften mit Array-Semantik.</li>\n<li>Komposition <code>+element</code> [1] auf <code>RestPrimitivePropertyDef</code>.</li>\n<li><strong>RestPrimitivePropertyDef</strong> (abstrakt): Basisklasse für primitive Eigenschaftsdefinitionen.</li>\n<li>Spezialisierungen: <code>RestStringPropertyDef</code>, <code>RestBooleanPropertyDef</code>, <code>RestAbstractNumericalPropertyDef</code> (abstrakt) sowie <code>RestObjectRef</code>.</li>\n<li><strong>RestStringPropertyDef</strong>:</li>\n<li>Attribut: <code>+ format :String [0..1]</code></li>\n<li>Komposition <code>+enum</code> [1..*] auf <code>RestEnumeratorDef</code>.</li>\n<li><strong>RestEnumeratorDef</strong>:</li>\n<li>Attribut: <code>+ value :String</code></li>\n<li><strong>RestBooleanPropertyDef</strong>: Keine eigenen Attribute modelliert.</li>\n<li><strong>RestAbstractNumericalPropertyDef</strong> (abstrakt):</li>\n<li>Attribute: <code>+ lowerLimit :Limit [0..1]</code>, <code>+ resolution :Float [0..1]</code>, <code>+ unit :String [0..1]</code>, <code>+ upperLimit :Limit [0..1]</code></li>\n<li>Spezialisierungen: <code>RestIntegerPropertyDef</code> und <code>RestNumberPropertyDef</code>.</li>\n<li><strong>RestIntegerPropertyDef</strong> / <strong>RestNumberPropertyDef</strong>: Konkrete Spezialisierungen ohne zusätzliche eigene Attribute im Diagramm.</li>\n<li><strong>RestObjectRef</strong>:</li>\n<li>Attribut: <code>+ role :String</code></li>\n<li>Assoziation / Referenz <code>+object</code> [0..*] zurück auf <code>RestElementDef</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Struktur von REST-Dienstbeschreibungen im AUTOSAR-Manifest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Modellierungswerkzeuge für AUTOSAR Adaptive Manifeste müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>RestElementDef</code> muss mindestens eine Eigenschaft besitzen (<code>+property</code> [1..*]).</li>\n<li>Eigenschaften können primitiv (<code>RestPrimitivePropertyDef</code>) oder als Array (<code>RestArrayPropertyDef</code>) ausgeprägt sein.</li>\n<li>Ein <code>RestArrayPropertyDef</code> referenziert über Komposition genau ein primitives Basiselement (<code>+element</code> [1]).</li>\n<li>Enumerationen werden über <code>RestStringPropertyDef</code> abgebildet, das mindestens einen <code>RestEnumeratorDef</code> über <code>+enum</code> [1..*] aggregieren kann.</li>\n<li>Komplexe Objektstrukturen und Schachtelungen werden über <code>RestObjectRef</code> realisiert, das auf <code>RestElementDef</code> (<code>+object</code> [0..*]) verweist und über das Attribut <code>role</code> semantisch qualifiziert wird.</li>\n<li>Numerische Grenzwerte und Auflösungen (<code>Limit</code>, <code>Float</code>, <code>Unit</code>) sind optional auf Ebene von <code>RestAbstractNumericalPropertyDef</code> definierbar.</li>\n</ul>"}, {"id": "FIG-88c217032b2050d8", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform (Metamodell-Ausschnitt des Manifests, Paket <code>M2::AUTOSARTemplates::AdaptivePlatform::ApplicationDesign::PortInterface::REST</code>). Das Diagramm spezifiziert die Metaklassen zur strukturellen Modellierung von REST-Elementen und deren Eigenschaftsdefinitionen (<code>REST elements</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>RestElementDef</strong> (spezialisiert <code>Identifiable</code>): Repräsentiert die Definition eines REST-Elements.</li>\n<li>Komposition <code>+property</code> [1..*] auf die abstrakte Metaklasse <code>RestAbstractPropertyDef</code>.</li>\n<li><strong>RestAbstractPropertyDef</strong> (spezialisiert <code>AtpStructureElement</code>, abstrakt): Basisklasse für Eigenschaften eines REST-Elements.</li>\n<li>Spezialisierungen: <code>RestPrimitivePropertyDef</code> (abstrakt) und <code>RestArrayPropertyDef</code>.</li>\n<li><strong>RestArrayPropertyDef</strong>: Modelliert Eigenschaften mit Array-Semantik.</li>\n<li>Komposition <code>+element</code> [1] auf <code>RestPrimitivePropertyDef</code>.</li>\n<li><strong>RestPrimitivePropertyDef</strong> (abstrakt): Basisklasse für primitive Eigenschaftsdefinitionen.</li>\n<li>Spezialisierungen: <code>RestStringPropertyDef</code>, <code>RestBooleanPropertyDef</code>, <code>RestAbstractNumericalPropertyDef</code> (abstrakt) sowie <code>RestObjectRef</code>.</li>\n<li><strong>RestStringPropertyDef</strong>:</li>\n<li>Attribut: <code>+ format: String [0..1]</code></li>\n<li>Komposition <code>+enum</code> [1..*] auf <code>RestEnumeratorDef</code>.</li>\n<li><strong>RestEnumeratorDef</strong>:</li>\n<li>Attribut: <code>+ value: String</code></li>\n<li><strong>RestBooleanPropertyDef</strong>: Keine eigenen Attribute modelliert.</li>\n<li><strong>RestAbstractNumericalPropertyDef</strong> (abstrakt):</li>\n<li>Attribute: <code>+ lowerLimit: Limit [0..1]</code>, <code>+ resolution: Float [0..1]</code>, <code>+ unit: String [0..1]</code>, <code>+ upperLimit: Limit [0..1]</code></li>\n<li>Spezialisierungen: <code>RestIntegerPropertyDef</code> und <code>RestNumberPropertyDef</code>.</li>\n<li><strong>RestIntegerPropertyDef</strong> / <strong>RestNumberPropertyDef</strong>: Konkrete Spezialisierungen ohne zusätzliche eigene Attribute im Diagramm.</li>\n<li><strong>RestObjectRef</strong>:</li>\n<li>Attribut: <code>+ role: String</code></li>\n<li>Assoziation / Referenz <code>+object</code> [0..*] zurück auf <code>RestElementDef</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Struktur von REST-Dienstbeschreibungen im AUTOSAR-Manifest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Modellierungswerkzeuge für AUTOSAR Adaptive Manifeste müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>RestElementDef</code> muss mindestens eine Eigenschaft besitzen (<code>+property</code> [1..*]).</li>\n<li>Eigenschaften können primitiv (<code>RestPrimitivePropertyDef</code>) oder als Array (<code>RestArrayPropertyDef</code>) ausgeprägt sein.</li>\n<li>Ein <code>RestArrayPropertyDef</code> referenziert über Komposition genau ein primitives Basiselement (<code>+element</code> [1]).</li>\n<li>Enumerationen werden über <code>RestStringPropertyDef</code> abgebildet, das mindestens einen <code>RestEnumeratorDef</code> über <code>+enum</code> [1..*] aggregieren kann.</li>\n<li>Komplexe Objektstrukturen und Schachtelungen werden über <code>RestObjectRef</code> realisiert, das auf <code>RestElementDef</code> (<code>+object</code> [0..*]) verweist und über das Attribut <code>role</code> semantisch qualifiziert wird.</li>\n<li>Numerische Grenzwerte und Auflösungen (<code>Limit</code>, <code>Float</code>, <code>Unit</code>) sind optional auf Ebene von <code>RestAbstractNumericalPropertyDef</code> definierbar.</li>\n</ul>"}, {"id": "FIG-57dd50eaee788aaf", "releases": ["R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform (Metamodell-Ausschnitt des Manifests, Paket <code>M2::AUTOSARTemplates::AdaptivePlatform::ApplicationDesign::PortInterface::REST</code>). Das Diagramm spezifiziert die Metaklassen zur strukturellen Modellierung von REST-Elementen und deren Eigenschaftsdefinitionen (<code>REST elements</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>RestElementDef</strong> (spezialisiert <code>Identifiable</code>): Repräsentiert die Definition eines REST-Elements.</li>\n<li>Komposition <code>+property</code> [1..*] auf die abstrakte Metaklasse <code>RestAbstractPropertyDef</code>.</li>\n<li><strong>RestAbstractPropertyDef</strong> (spezialisiert <code>AtpStructureElement</code>, abstrakt): Basisklasse für Eigenschaften eines REST-Elements.</li>\n<li>Spezialisierungen: <code>RestPrimitivePropertyDef</code> (abstrakt) und <code>RestArrayPropertyDef</code>.</li>\n<li><strong>RestArrayPropertyDef</strong>: Modelliert Eigenschaften mit Array-Semantik.</li>\n<li>Komposition <code>+element</code> [1] auf <code>RestPrimitivePropertyDef</code>.</li>\n<li><strong>RestPrimitivePropertyDef</strong> (abstrakt): Basisklasse für primitive Eigenschaftsdefinitionen.</li>\n<li>Spezialisierungen: <code>RestStringPropertyDef</code>, <code>RestBooleanPropertyDef</code>, <code>RestAbstractNumericalPropertyDef</code> (abstrakt) sowie <code>RestObjectRef</code>.</li>\n<li><strong>RestStringPropertyDef</strong>:</li>\n<li>Attribut: <code>+ format: String [0..1]</code></li>\n<li>Komposition <code>+enum</code> [1..*] auf <code>RestEnumeratorDef</code>.</li>\n<li><strong>RestEnumeratorDef</strong>:</li>\n<li>Attribut: <code>+ value: String</code></li>\n<li><strong>RestBooleanPropertyDef</strong>: Keine eigenen Attribute modelliert.</li>\n<li><strong>RestAbstractNumericalPropertyDef</strong> (abstrakt):</li>\n<li>Attribute: <code>+ lowerLimit: Limit [0..1]</code>, <code>+ resolution: Float [0..1]</code>, <code>+ unit: String [0..1]</code>, <code>+ upperLimit: Limit [0..1]</code></li>\n<li>Spezialisierungen: <code>RestIntegerPropertyDef</code> und <code>RestNumberPropertyDef</code>.</li>\n<li><strong>RestIntegerPropertyDef</strong> / <strong>RestNumberPropertyDef</strong>: Konkrete Spezialisierungen ohne zusätzliche eigene Attribute im Diagramm.</li>\n<li><strong>RestObjectRef</strong>:</li>\n<li>Attribut: <code>+ role: String</code></li>\n<li>Assoziation / Referenz <code>+object</code> [0..*] zurück auf <code>RestElementDef</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die deklarative Struktur von REST-Dienstbeschreibungen im AUTOSAR-Manifest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Modellierungswerkzeuge für AUTOSAR Adaptive Manifeste müssen beachten:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>RestElementDef</code> muss mindestens eine Eigenschaft besitzen (<code>+property</code> [1..*]).</li>\n<li>Eigenschaften können primitiv (<code>RestPrimitivePropertyDef</code>) oder als Array (<code>RestArrayPropertyDef</code>) ausgeprägt sein.</li>\n<li>Ein <code>RestArrayPropertyDef</code> referenziert über Komposition genau ein primitives Basiselement (<code>+element</code> [1]).</li>\n<li>Enumerationen werden über <code>RestStringPropertyDef</code> abgebildet, das mindestens einen <code>RestEnumeratorDef</code> über <code>+enum</code> [1..*] aggregieren kann.</li>\n<li>Komplexe Objektstrukturen und Schachtelungen werden über <code>RestObjectRef</code> realisiert, das auf <code>RestElementDef</code> (<code>+object</code> [0..*]) verweist und über das Attribut <code>role</code> semantisch qualifiziert wird.</li>\n<li>Numerische Grenzwerte und Auflösungen (<code>Limit</code>, <code>Float</code>, <code>Unit</code>) sind optional auf Ebene von <code>RestAbstractNumericalPropertyDef</code> definierbar.</li>\n</ul>"}], "trans": [{"from": "FIG-a4e5a10a9ef049c0", "to": "FIG-288472df44790296", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-288472df44790296", "to": "FIG-88c217032b2050d8", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>RestStringPropertyDef</strong>: Attributschreibweise von <code>+ format :String [0..1]</code> zu <code>+ format: String [0..1]</code> vereinheitlicht (Leerzeichen vor dem Doppelpunkt entfernt).</li>\n<li><strong>RestAbstractNumericalPropertyDef</strong>: Attributschreibweisen von <code>+ lowerLimit :Limit [0..1]</code>, <code>+ resolution :Float [0..1]</code>, <code>+ unit :String [0..1]</code> und <code>+ upperLimit :Limit [0..1]</code> zu <code>+ lowerLimit: Limit [0..1]</code>, <code>+ resolution: Float [0..1]</code>, <code>+ unit: String [0..1]</code> und <code>+ upperLimit: Limit [0..1]</code> angepasst (Leerzeichen vor dem Doppelpunkt entfernt).</li>\n<li><strong>RestObjectRef</strong>: Attributschreibweise von <code>+ role :String</code> zu <code>+ role: String</code> angepasst (Leerzeichen vor dem Doppelpunkt entfernt).</li>\n<li><strong>RestEnumeratorDef</strong>: Attributschreibweise von <code>+ value :String</code> zu <code>+ value: String</code> angepasst (Leerzeichen vor dem Doppelpunkt entfernt).</li>\n</ul>"}, {"from": "FIG-88c217032b2050d8", "to": "FIG-57dd50eaee788aaf", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-57dd50eaee788aaf", "to": "FIG-88c217032b2050d8", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
